// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Easing,
} from '../remotionShim';
import { evolvePath } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type SalesChartProps = Record<string, any>;

const DATA_POINTS = [
  { year: 1997, units: 0 },
  { year: 1998, units: 2 },
  { year: 1999, units: 4 },
  { year: 2000, units: 6 },
  { year: 2001, units: 26 },
  { year: 2002, units: 52 },
  { year: 2004, units: 57 },
  { year: 2006, units: 60 },
  { year: 2008, units: 63 },
  { year: 2010, units: 65 },
  { year: 2012, units: 66 },
  { year: 2015, units: 68 },
  { year: 2021, units: 76 },
  { year: 2026, units: 82 },
];

const X_GRID_YEARS = [1997, 2000, 2005, 2010, 2015, 2021, 2026];
const Y_GRID_UNITS = [0, 20, 40, 60, 80];

// Define a smooth standard ease for opacities and crossfades
const smoothEase = Easing.bezier(0.4, 0, 0.2, 1);

const SalesChart: React.FC<SalesChartProps> = ({
  title = "DMX: GLOBAL UNIT SALES GROWTH (1997-2026)",
  yAxisLabel = "TOTAL UNITS (MILLIONS)",
  xAxisLabel = "YEAR",
  debutText = "DEBUT",
  peakText = "PEAK",
  peakSubText = "(98-03)",
  finalValueText = "82 MILLION",
  finalSubText = "+30% ADJ.",
  backgroundColor = "#001f3f",
  transparentBackground = false,
  chartColor = "#001f3f",
  lineColor = "#ffcc00",
  durationInSeconds = 30,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const containerStyle: React.CSSProperties = {
    backgroundColor: transparentBackground ? "transparent" : backgroundColor,
    fontFamily: interFamily,
  };

  // Responsiveness scale
  const s = Math.min(width, height) / 1080;
  const padding = {
    top: 220 * s,
    right: 120 * s,
    bottom: 160 * s,
    left: 180 * s,
  };

  const chartWidth = width - padding.left - padding.right;
  const chartHeight = height - padding.top - padding.bottom;

  // Coordinate mappers
  const getX = (year: number) =>
    padding.left + ((year - 1997) / 29) * chartWidth;
  const getY = (units: number) =>
    padding.top + chartHeight - (units / 85) * chartHeight;

  // Pre-calculate path strings and segment lengths
  const getPathData = () => {
    if (DATA_POINTS.length === 0) return "";
    let d = `M ${getX(DATA_POINTS[0].year)} ${getY(DATA_POINTS[0].units)}`;
    for (let i = 1; i < DATA_POINTS.length; i++) {
      d += ` L ${getX(DATA_POINTS[i].year)} ${getY(DATA_POINTS[i].units)}`;
    }
    return d;
  };

  const getSegmentLengths = () => {
    let totalLength = 0;
    const thresh = [0];
    for (let i = 1; i < DATA_POINTS.length; i++) {
      const prev = DATA_POINTS[i - 1];
      const curr = DATA_POINTS[i];
      const dx = getX(curr.year) - getX(prev.year);
      const dy = getY(curr.units) - getY(prev.units);
      const dist = Math.sqrt(dx * dx + dy * dy);
      totalLength += dist;
      thresh.push(totalLength);
    }
    return thresh.map((t) => (totalLength === 0 ? 0 : t / totalLength));
  };

  const pathString = getPathData();
  const thresholds = getSegmentLengths();

  // Animation Timings
  const titleY = spring({
    fps,
    frame,
    config: { damping: 15, mass: 0.8 },
    from: -150 * s,
    to: 80 * s,
  });

  const chartBgOpacity = interpolate(frame, [20, 35], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: smoothEase,
  });

  const gridOpacity = interpolate(frame, [10, 25], [0, 0.6], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: smoothEase,
  });

  const labelsOpacity = interpolate(frame, [30, 45], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: smoothEase,
  });

  // Adding a graceful cubic ease-out to the line draw
  const lineProgress = interpolate(frame, [50, 170], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  const { strokeDasharray, strokeDashoffset } = evolvePath(
    lineProgress,
    pathString
  );

  // Annotations
  const debutSlide = spring({ fps, frame: frame - 50, config: { damping: 15, mass: 0.8 } });
  const debutOpacity = interpolate(frame, [50, 60], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: smoothEase,
  });
  const debutYOffset = interpolate(debutSlide, [0, 1], [20 * s, 0]);
  const debutArrowEnd = { x: getX(1997) + 5 * s, y: getY(0) - 16 * s };
  const debutArrowStart = { x: getX(1997) + 15 * s, y: getY(0) - 35 * s };
  const debutAngle = (Math.atan2(
    debutArrowEnd.y - debutArrowStart.y,
    debutArrowEnd.x - debutArrowStart.x
  ) * 180) / Math.PI;

  // Sync peak frame exactly with the non-linear line draw (inverse of cubic ease-out)
  const peakT = 1 - Math.cbrt(Math.max(0, 1 - thresholds[5]));
  const peakFrame = 50 + peakT * 120;
  
  const peakSlide = spring({
    fps,
    frame: frame - peakFrame,
    config: { damping: 15, mass: 0.8 },
  });
  const peakOpacity = interpolate(
    frame,
    [peakFrame, peakFrame + 10],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: smoothEase }
  );
  const peakYOffset = interpolate(peakSlide, [0, 1], [20 * s, 0]);
  const peakArrowEnd = { x: getX(2002) - 16 * s, y: getY(52) - 16 * s };
  const peakArrowStart = { x: getX(2002) - 50 * s, y: getY(52) - 50 * s };
  const peakAngle = (Math.atan2(
    peakArrowEnd.y - peakArrowStart.y,
    peakArrowEnd.x - peakArrowStart.x
  ) * 180) / Math.PI;

  const adjSlide = spring({ fps, frame: frame - 170, config: { damping: 15, mass: 0.8 } });
  const adjOpacity = interpolate(frame, [170, 180], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: smoothEase,
  });
  const adjYOffset = interpolate(adjSlide, [0, 1], [20 * s, 0]);
  const annotArrowEnd = { x: getX(2026) - 20 * s, y: getY(82) + 20 * s };
  const annotArrowStart = { x: getX(2026) - 60 * s, y: getY(82) + 40 * s };
  const annotAngle = (Math.atan2(
    annotArrowEnd.y - annotArrowStart.y,
    annotArrowEnd.x - annotArrowStart.x
  ) * 180) / Math.PI;

  const mainArrowScale = spring({
    fps,
    frame: frame - 170,
    config: { damping: 15, mass: 0.8 },
  });
  const mainArrowDx = getX(2026) - getX(2021);
  const mainArrowDy = getY(82) - getY(76);
  const mainArrowAngle = (Math.atan2(mainArrowDy, mainArrowDx) * 180) / Math.PI;

  return (
    <AbsoluteFill style={containerStyle}>
      {/* Title */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          padding: `0 ${60 * s}px`,
          boxSizing: "border-box",
          top: titleY,
          textAlign: "center",
          color: "#ffffff",
          fontSize: 48 * s,
          fontWeight: 800,
          letterSpacing: "0.02em",
          textTransform: "uppercase",
        }}
      >
        {title}
      </div>

      <svg
        width="100%"
        height="100%"
        style={{ position: "absolute", top: 0, left: 0 }}
      >
        {/* Chart Area Background */}
        <rect
          x={padding.left}
          y={padding.top}
          width={chartWidth}
          height={chartHeight}
          fill={chartColor}
          opacity={chartBgOpacity}
          rx={16 * s}
        />

        {/* X Grid Lines & Labels */}
        {X_GRID_YEARS.map((year) => {
          const isOrigin = year === 1997;
          return (
            <g key={`x-${year}`}>
              <line
                x1={getX(year)}
                y1={padding.top}
                x2={getX(year)}
                y2={padding.top + chartHeight}
                stroke={isOrigin ? "rgba(255,255,255,0.5)" : "rgba(255,255,255,0.2)"}
                strokeWidth={isOrigin ? 3 * s : 2 * s}
                strokeDasharray={isOrigin ? "none" : `${8 * s}, ${8 * s}`}
                opacity={isOrigin ? labelsOpacity : gridOpacity}
              />
              <text
                x={getX(year)}
                y={padding.top + chartHeight + 45 * s}
                fill="rgba(255,255,255,0.9)"
                fontSize={26 * s}
                fontWeight="500"
                opacity={labelsOpacity}
                textAnchor="middle"
              >
                {year}
              </text>
            </g>
          );
        })}

        {/* X Axis Title */}
        <text
          x={getX(2011)}
          y={padding.top + chartHeight + 100 * s}
          fill="#ffffff"
          fontSize={28 * s}
          fontWeight="bold"
          letterSpacing="0.05em"
          opacity={labelsOpacity}
          textAnchor="middle"
        >
          {xAxisLabel}
        </text>

        {/* Y Grid Lines & Labels */}
        {Y_GRID_UNITS.map((unit) => {
          const isBase = unit === 0;
          return (
            <g key={`y-${unit}`}>
              <line
                x1={padding.left}
                y1={getY(unit)}
                x2={padding.left + chartWidth}
                y2={getY(unit)}
                stroke={isBase ? "rgba(255,255,255,0.5)" : "rgba(255,255,255,0.2)"}
                strokeWidth={isBase ? 3 * s : 2 * s}
                strokeDasharray={isBase ? "none" : `${8 * s}, ${8 * s}`}
                opacity={isBase ? labelsOpacity : gridOpacity}
              />
              <text
                x={padding.left - 24 * s}
                y={getY(unit) + 8 * s}
                fill="rgba(255,255,255,0.9)"
                fontSize={26 * s}
                fontWeight="500"
                opacity={labelsOpacity}
                textAnchor="end"
              >
                {unit}M
              </text>
            </g>
          );
        })}

        {/* Y Axis Title */}
        <g
          transform={`translate(${padding.left - 110 * s}, ${
            padding.top + chartHeight / 2
          }) rotate(-90)`}
          opacity={labelsOpacity}
        >
          <text
            x={0}
            y={0}
            fill="#ffffff"
            fontSize={28 * s}
            fontWeight="bold"
            letterSpacing="0.05em"
            textAnchor="middle"
          >
            {yAxisLabel}
          </text>
        </g>

        {/* Main Line Path */}
        <path
          d={pathString}
          fill="none"
          stroke={lineColor}
          strokeWidth={12 * s}
          strokeDasharray={strokeDasharray}
          strokeDashoffset={strokeDashoffset}
          strokeLinecap="round"
          strokeLinejoin="round"
        />

        {/* Data Points */}
        {DATA_POINTS.map((d, i) => {
          // Sync exact frame with the cubic ease-out of the line drawing
          const t = 1 - Math.cbrt(Math.max(0, 1 - thresholds[i]));
          const popFrame = 50 + t * 120;
          
          const pointScale = spring({
            fps,
            frame: frame - popFrame,
            config: { damping: 15, mass: 0.8 },
            durationInFrames: 20,
          });

          return (
            <circle
              key={`dot-${i}`}
              cx={getX(d.year)}
              cy={getY(d.units)}
              r={9 * s * pointScale}
              fill={backgroundColor}
              stroke={lineColor}
              strokeWidth={4 * s * pointScale}
            />
          );
        })}

        {/* Main Line Arrowhead */}
        <g
          transform={`translate(${getX(2026)}, ${getY(
            82
          )}) rotate(${mainArrowAngle}) scale(${mainArrowScale})`}
        >
          <polygon
            points={`${-35 * s},${-18 * s} 0,0 ${-35 * s},${18 * s}`}
            fill={lineColor}
            stroke={lineColor}
            strokeWidth={2 * s}
            strokeLinejoin="round"
          />
        </g>

        {/* Annotations */}
        <g transform={`translate(0, ${debutYOffset})`} opacity={debutOpacity}>
          <text
            x={getX(1997) + 12 * s}
            y={getY(0) - 50 * s}
            fill="#ffffff"
            fontSize={28 * s}
            fontWeight="700"
          >
            {debutText}
          </text>
          <line
            x1={debutArrowStart.x}
            y1={debutArrowStart.y}
            x2={debutArrowEnd.x}
            y2={debutArrowEnd.y}
            stroke="#ffffff"
            strokeWidth={3 * s}
            strokeLinecap="round"
          />
          <g
            transform={`translate(${debutArrowEnd.x}, ${debutArrowEnd.y}) rotate(${debutAngle})`}
          >
            <polygon
              points={`${-10 * s},${-6 * s} 2 * s,0 ${-10 * s},${6 * s}`}
              fill="#ffffff"
            />
          </g>
        </g>

        <g transform={`translate(0, ${peakYOffset})`} opacity={peakOpacity}>
          <text
            x={getX(2002) - 130 * s}
            y={getY(52) - 85 * s}
            fill="#ffffff"
            fontSize={30 * s}
            fontWeight="700"
          >
            {peakText}
          </text>
          <text
            x={getX(2002) - 130 * s}
            y={getY(52) - 50 * s}
            fill="rgba(255,255,255,0.85)"
            fontSize={24 * s}
            fontWeight="600"
          >
            {peakSubText}
          </text>
          <line
            x1={peakArrowStart.x}
            y1={peakArrowStart.y}
            x2={peakArrowEnd.x}
            y2={peakArrowEnd.y}
            stroke="#ffffff"
            strokeWidth={3 * s}
            strokeLinecap="round"
          />
          <g
            transform={`translate(${peakArrowEnd.x}, ${peakArrowEnd.y}) rotate(${peakAngle})`}
          >
            <polygon
              points={`${-10 * s},${-6 * s} 2 * s,0 ${-10 * s},${6 * s}`}
              fill="#ffffff"
            />
          </g>
        </g>

        <g transform={`translate(0, ${adjYOffset})`} opacity={adjOpacity}>
          <text
            x={getX(2026) - 220 * s}
            y={getY(82) + 70 * s}
            fill="#ffffff"
            fontSize={34 * s}
            fontWeight="800"
          >
            {finalValueText}
          </text>
          <text
            x={getX(2026) - 170 * s}
            y={getY(82) + 110 * s}
            fill="rgba(255,255,255,0.85)"
            fontSize={24 * s}
            fontWeight="600"
          >
            {finalSubText}
          </text>
          <line
            x1={annotArrowStart.x}
            y1={annotArrowStart.y}
            x2={annotArrowEnd.x}
            y2={annotArrowEnd.y}
            stroke="#ffffff"
            strokeWidth={3 * s}
            strokeLinecap="round"
          />
          <g
            transform={`translate(${annotArrowEnd.x}, ${annotArrowEnd.y}) rotate(${annotAngle})`}
          >
            <polygon
              points={`${-10 * s},${-6 * s} 2 * s,0 ${-10 * s},${6 * s}`}
              fill="#ffffff"
            />
          </g>
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default SalesChart;